# TIENG HAN MR LEE - Installer 1-6 / Daily Streak / Speaking 2026
# Windows PowerShell 5.1 compatible, only UTF-8 and built-in GzipStream.
param([string]$WebsitePath = "")
$ErrorActionPreference = 'Stop'
if([string]::IsNullOrWhiteSpace($WebsitePath)) { $WebsitePath = Split-Path -Parent $MyInvocation.MyCommand.Path }
$WebsitePath = [System.IO.Path]::GetFullPath($WebsitePath)
if(-not (Test-Path (Join-Path $WebsitePath 'index.html'))) {
 throw "Không tìm thấy index.html trong $WebsitePath. Hãy chép file cài đặt vào thư mục gốc website, rồi chạy lại."
}
$Utf8 = New-Object System.Text.UTF8Encoding($false)
$Stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$BackupRoot = Join-Path (Split-Path -Parent $WebsitePath) ('.mrlee-backup-roadmap-' + $Stamp)
New-Item -Path $BackupRoot -ItemType Directory -Force | Out-Null
function Backup-File([string]$relative) {
 $target = Join-Path $WebsitePath $relative
 if(Test-Path $target) {
   $destination = Join-Path $BackupRoot $relative
   $parent = Split-Path -Parent $destination
   if(-not (Test-Path $parent)){ New-Item -ItemType Directory -Path $parent -Force | Out-Null }
   Copy-Item -LiteralPath $target -Destination $destination -Force
 }
}
function Put-Compressed([string]$relative,[string]$encoded,[bool]$overwrite) {
 $target = Join-Path $WebsitePath $relative
 if((Test-Path $target) -and (-not $overwrite)){ Write-Host "GIỮ NGUYÊN: $relative"; return }
 $raw = [Convert]::FromBase64String(($encoded -replace '\s',''))
 $inputStream = [System.IO.MemoryStream]::new($raw)
 $zip = [System.IO.Compression.GzipStream]::new($inputStream, [System.IO.Compression.CompressionMode]::Decompress)
 $buffer = [System.IO.MemoryStream]::new()
 try { $zip.CopyTo($buffer) } finally { $zip.Dispose(); $inputStream.Dispose() }
 Backup-File $relative
 [System.IO.File]::WriteAllBytes($target,$buffer.ToArray())
 $buffer.Dispose()
 Write-Host "ĐÃ CÀI: $relative"
}
function Patch-Html([string]$file,[bool]$link) {
 $path=Join-Path $WebsitePath $file
 if(-not (Test-Path $path)){ return }
 $source=[System.IO.File]::ReadAllText($path,$Utf8)
 $result=$source
 if($result -notmatch 'mrlee-daily-boot[.]js') {
   $tag='<script type="module" src="mrlee-daily-boot.js?v=20261010"></script>'
   $result=[System.Text.RegularExpressions.Regex]::Replace($result,'(?i)</body>',($tag + "`r`n</body>"),1)
 }
 if($link -and $result -notmatch 'href="lo-trinh-1-6[.]html"') {
   $old='<a href="bai-hoc.html">Bài học</a>'
   if($result.Contains($old)) {
     $result=$result.Replace($old,($old + "`r`n" + '<a href="lo-trinh-1-6.html">Lộ trình 1–6</a>'))
   } else {
     $fallback='<a href="lo-trinh-1-6.html" style="display:inline-flex;padding:8px 12px;margin:5px;border-radius:10px;background:#e5f3ff;color:#215e91;font-weight:700;text-decoration:none">📚 Lộ trình 1–6</a>'
     $result=[System.Text.RegularExpressions.Regex]::Replace($result,'(?i)<main\b',($fallback+'<main'),1)
   }
 }
 if($result -ne $source){
   Backup-File $file
   [System.IO.File]::WriteAllText($path,$result,$Utf8)
   Write-Host "CẬP NHẬT LINK/THƯỞNG: $file"
 }
}
function Patch-Gate([string]$file){
 $path=Join-Path $WebsitePath $file
 if(-not (Test-Path $path)){return}
 $source=[System.IO.File]::ReadAllText($path,$Utf8)
 $result=$source
 if($result -notmatch 'mrlee-points[.]css'){
  $result=[System.Text.RegularExpressions.Regex]::Replace($result,'(?i)</head>',('<link rel="stylesheet" href="mrlee-points.css?v=20261010">' + "`r`n</head>"),1)
 }
 if($result -notmatch 'mrlee-points-gate[.]js'){
  $result=[System.Text.RegularExpressions.Regex]::Replace($result,'(?i)</body>',('<script type="module" src="mrlee-points-gate.js?v=20261010"></script>' + "`r`n</body>"),1)
 }
 if($result -ne $source){ Backup-File $file; [System.IO.File]::WriteAllText($path,$result,$Utf8); Write-Host "CẬP NHẬT LUYỆN NÓI: $file" }
}
Write-Host '===== MR LEE LO TRINH 1-6 & DAILY STREAK =====' -ForegroundColor Cyan
Write-Host "THU MUC: $WebsitePath"
